-- ISOLATED TEST DATABASE ONLY. Metadata-compatible fixture; no production records.
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('test.auth_uid', true), '')::uuid $$;
CREATE TABLE public.action_logs("id" uuid DEFAULT gen_random_uuid() NOT NULL,"user_id" text DEFAULT ''::text NOT NULL,"user_nome" text DEFAULT ''::text NOT NULL,"role" text DEFAULT ''::text NOT NULL,"unidade_id" text DEFAULT ''::text NOT NULL,"acao" text NOT NULL,"entidade" text NOT NULL,"entidade_id" text DEFAULT ''::text NOT NULL,"detalhes" jsonb DEFAULT '{}'::jsonb NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"modulo" text DEFAULT ''::text NOT NULL,"status" text DEFAULT 'sucesso'::text NOT NULL,"erro" text DEFAULT ''::text,"ip" text DEFAULT ''::text,"acao_legivel" text,"tipo_evento" text,"origem" text,"paciente_id" text,"paciente_nome" text,"profissional_id" text,"profissional_nome" text,"agendamento_id" text,"prontuario_id" text,"documento_id" text,"unidade_nome" text,"before" jsonb,"after" jsonb,"changes" jsonb,"campos_alterados" text[],"resumo_alteracao" text,"user_agent" text,"navegador" text,"sistema_operacional" text,"dispositivo" text,"rota" text,"error_message" text,"error_code" text,"metadata" jsonb DEFAULT '{}'::jsonb);
CREATE TABLE public.bloqueios("id" uuid DEFAULT gen_random_uuid() NOT NULL,"profissional_id" text DEFAULT ''::text,"unidade_id" text DEFAULT ''::text,"tipo" text DEFAULT 'feriado'::text NOT NULL,"titulo" text DEFAULT ''::text NOT NULL,"data_inicio" date NOT NULL,"data_fim" date NOT NULL,"hora_inicio" text DEFAULT ''::text,"hora_fim" text DEFAULT ''::text,"dia_inteiro" bool DEFAULT true,"criado_em" timestamptz DEFAULT now(),"criado_por" text DEFAULT ''::text NOT NULL);
CREATE TABLE public.funcionarios("id" uuid DEFAULT gen_random_uuid() NOT NULL,"auth_user_id" uuid,"nome" text NOT NULL,"usuario" text NOT NULL,"email" text NOT NULL,"setor" text DEFAULT ''::text,"unidade_id" text DEFAULT ''::text,"sala_id" text DEFAULT ''::text,"cargo" text DEFAULT ''::text,"role" text DEFAULT 'recepcao'::text NOT NULL,"ativo" bool DEFAULT true,"criado_em" timestamptz DEFAULT now(),"criado_por" text DEFAULT ''::text,"tempo_atendimento" int4 DEFAULT 30 NOT NULL,"profissao" text DEFAULT ''::text NOT NULL,"tipo_conselho" text DEFAULT ''::text NOT NULL,"numero_conselho" text DEFAULT ''::text NOT NULL,"uf_conselho" text DEFAULT ''::text NOT NULL,"pode_agendar_retorno" bool DEFAULT false NOT NULL,"cpf" text DEFAULT ''::text NOT NULL,"coren" varchar DEFAULT ''::character varying,"custom_data" jsonb DEFAULT '{}'::jsonb NOT NULL);
CREATE TABLE public.permissoes("id" uuid DEFAULT gen_random_uuid() NOT NULL,"perfil" text NOT NULL,"modulo" text NOT NULL,"can_view" bool DEFAULT false NOT NULL,"can_create" bool DEFAULT false NOT NULL,"can_edit" bool DEFAULT false NOT NULL,"can_delete" bool DEFAULT false NOT NULL,"can_execute" bool DEFAULT false NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"unidade_id" text DEFAULT ''::text NOT NULL,"can_print" bool DEFAULT false,"can_export" bool DEFAULT false,"can_attach" bool DEFAULT false,"can_sign" bool DEFAULT false,"can_approve" bool DEFAULT false,"can_cancel" bool DEFAULT false,"can_configure" bool DEFAULT false,"granular_actions" jsonb DEFAULT '{}'::jsonb);
CREATE TABLE public.permissoes_usuario("id" uuid DEFAULT gen_random_uuid() NOT NULL,"user_id" text NOT NULL,"unidade_id" text DEFAULT ''::text NOT NULL,"modulo" text NOT NULL,"can_view" bool,"can_create" bool,"can_edit" bool,"can_delete" bool,"can_execute" bool,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"can_print" bool,"can_export" bool,"can_attach" bool,"can_sign" bool,"can_approve" bool,"can_cancel" bool,"can_configure" bool,"granular_actions" jsonb DEFAULT '{}'::jsonb);
CREATE TABLE public.treatment_cycles("id" uuid DEFAULT gen_random_uuid() NOT NULL,"patient_id" text NOT NULL,"professional_id" text NOT NULL,"unit_id" text DEFAULT ''::text NOT NULL,"specialty" text DEFAULT ''::text NOT NULL,"treatment_type" text DEFAULT ''::text NOT NULL,"start_date" date DEFAULT CURRENT_DATE NOT NULL,"end_date_predicted" date,"total_sessions" int4 DEFAULT 1 NOT NULL,"sessions_done" int4 DEFAULT 0 NOT NULL,"frequency" text DEFAULT 'semanal'::text NOT NULL,"status" text DEFAULT 'em_andamento'::text NOT NULL,"clinical_notes" text DEFAULT ''::text NOT NULL,"created_by" text DEFAULT ''::text NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"pts_id" uuid,"custom_data" jsonb DEFAULT '{}'::jsonb NOT NULL);
CREATE TABLE public.treatment_extensions("id" uuid DEFAULT gen_random_uuid() NOT NULL,"cycle_id" uuid NOT NULL,"previous_sessions" int4 NOT NULL,"new_sessions" int4 NOT NULL,"previous_end_date" date,"new_end_date" date,"reason" text DEFAULT ''::text NOT NULL,"changed_by" text DEFAULT ''::text NOT NULL,"changed_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.treatment_sessions("id" uuid DEFAULT gen_random_uuid() NOT NULL,"cycle_id" uuid NOT NULL,"patient_id" text NOT NULL,"professional_id" text NOT NULL,"appointment_id" text,"session_number" int4 DEFAULT 1 NOT NULL,"total_sessions" int4 DEFAULT 1 NOT NULL,"scheduled_date" date DEFAULT CURRENT_DATE NOT NULL,"status" text DEFAULT 'agendada'::text NOT NULL,"absence_type" text,"clinical_notes" text DEFAULT ''::text NOT NULL,"procedure_done" text DEFAULT ''::text NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"tipo_falta" text,"falta_justificativa" text,"falta_liberada" bool DEFAULT false NOT NULL,"liberada_em" timestamptz,"liberada_por" uuid,"motivo_liberacao" text);
CREATE TABLE public.pacientes(id text PRIMARY KEY, nome text, unidade_id text);
CREATE TABLE public.agendamentos(id text PRIMARY KEY, paciente_id text, profissional_id text, unidade_id text, data date, hora text, status text);
CREATE TABLE public.pts(id uuid PRIMARY KEY, patient_id text, unit_id text);
